_FALLBACK_WORKFLOW_ENGINE = '''\
"""Approval workflow state machine — generated by AetherOS (fallback)."""
from __future__ import annotations
import enum
import logging
from dataclasses import dataclass
from typing import Any, Dict, List, Optional

logger = logging.getLogger(__name__)


class WorkflowState(str, enum.Enum):
    DRAFT = "draft"
    PENDING_APPROVAL = "pending_approval"
    APPROVED = "approved"
    REJECTED = "rejected"
    CANCELLED = "cancelled"
    COMPLETED = "completed"


@dataclass
class WorkflowTransition:
    from_state: str
    to_state: str
    actor: str          # role that may trigger this transition
    condition: str = ""
    action: str = ""    # side-effect to trigger (e.g. "send_email")


class WorkflowEngine:
    """State machine engine for {domain} approval workflows."""

    WORKFLOWS: Dict[str, List[WorkflowTransition]] = {{
        "default": [
            WorkflowTransition("draft", "pending_approval", "Staff", action="notify_manager"),
            WorkflowTransition("pending_approval", "approved", "Manager", action="notify_submitter"),
            WorkflowTransition("pending_approval", "rejected", "Manager", action="notify_submitter"),
            WorkflowTransition("approved", "completed", "Admin"),
            WorkflowTransition("*", "cancelled", "Admin"),
        ],
    }}

    async def transition(
        self,
        db: Any,
        entity_type: str,
        entity_id: Any,
        new_state: str,
        actor_role: str,
        actor_id: Any,
    ) -> bool:
        """Apply a workflow transition. Returns True if successful."""
        transitions = self.WORKFLOWS.get(entity_type, self.WORKFLOWS.get("default", []))
        allowed = [
            t for t in transitions
            if t.actor in (actor_role, "Admin", "*")
            and t.to_state == new_state
        ]
        if not allowed:
            logger.warning(
                "WorkflowEngine: %s cannot transition %s to %s",
                actor_role, entity_type, new_state,
            )
            return False
        logger.info(
            "WorkflowEngine: %s → %s (entity=%s id=%s actor=%s)",
            entity_type, new_state, entity_type, entity_id, actor_role,
        )
        return True

    def get_available_transitions(
        self, entity_type: str, current_state: str, actor_role: str
    ) -> List[str]:
        """Return list of states the actor can transition to from current_state."""
        transitions = self.WORKFLOWS.get(entity_type, self.WORKFLOWS.get("default", []))
        return [
            t.to_state
            for t in transitions
            if t.actor in (actor_role, "Admin", "*")
            and t.from_state in (current_state, "*")
        ]


workflow_engine = WorkflowEngine()
'''

_FALLBACK_BUSINESS_RULES = '''\
"""Business rules and calculation engine — generated by AetherOS (fallback)."""
from __future__ import annotations
import logging
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, Dict, Optional

logger = logging.getLogger(__name__)


class BusinessRules:
    """Core business rules and calculation logic for the {domain} domain application {project_name}."""

    # ── Validation rules ──────────────────────────────────────────────────────

    @classmethod
    def validate_positive_amount(cls, amount: float, field_name: str = "amount") -> None:
        """Amount fields must be positive non-zero values."""
        if amount is None or amount <= 0:
            raise ValueError(f"{{field_name}} must be a positive value, got {{amount}}")

    @classmethod
    def validate_non_empty_string(cls, value: str, field_name: str) -> None:
        """String fields must not be empty or whitespace-only."""
        if not value or not value.strip():
            raise ValueError(f"{{field_name}} must not be empty")

    @classmethod
    def validate_percentage(cls, value: float, field_name: str = "percentage") -> None:
        """Percentage values must be between 0 and 100."""
        if value < 0 or value > 100:
            raise ValueError(f"{{field_name}} must be between 0 and 100, got {{value}}")

    # ── Calculation formulas ──────────────────────────────────────────────────

    @classmethod
    def calculate_tax(cls, subtotal: float, tax_rate: float = 0.0) -> float:
        """Calculate tax amount from subtotal and rate (0.0–1.0)."""
        cls.validate_positive_amount(subtotal, "subtotal")
        cls.validate_percentage(tax_rate * 100, "tax_rate (x100)")
        return round(subtotal * tax_rate, 2)

    @classmethod
    def calculate_discount(cls, subtotal: float, discount_rate: float) -> float:
        """Calculate discount amount from subtotal and discount rate (0.0–1.0)."""
        cls.validate_positive_amount(subtotal, "subtotal")
        cls.validate_percentage(discount_rate * 100, "discount_rate (x100)")
        return round(subtotal * discount_rate, 2)

    @classmethod
    def calculate_total(
        cls, subtotal: float, tax_rate: float = 0.0, discount_rate: float = 0.0
    ) -> Dict[str, float]:
        """Calculate order total with tax and discount."""
        cls.validate_positive_amount(subtotal, "subtotal")
        tax = cls.calculate_tax(subtotal, tax_rate)
        discount = cls.calculate_discount(subtotal, discount_rate)
        total = round(subtotal + tax - discount, 2)
        return {{
            "subtotal": subtotal,
            "tax": tax,
            "discount": discount,
            "total": total,
        }}

    # ── Business constraints ─────────────────────────────────────────────────

    @classmethod
    def enforce_max_concurrent(cls, current_count: int, max_allowed: int, resource_name: str) -> None:
        """Enforce maximum concurrent resource limit."""
        if current_count >= max_allowed:
            raise ValueError(
                f"Maximum of {{max_allowed}} concurrent {{resource_name}} reached (current: {{current_count}})"
            )

    @classmethod
    def check_eligibility(cls, data: Dict[str, Any], required_fields: list) -> bool:
        """Check if all required eligibility fields are present and truthy."""
        missing = [f for f in required_fields if not data.get(f)]
        if missing:
            raise ValueError(f"Eligibility check failed: missing required fields: {{', '.join(missing)}}")
        return True


business_rules = BusinessRules()
'''


def get_responsive_email_template(
    project_name: str, body_content: str, primary_color: str = "#4f46e5"
) -> str:
    """Return a responsive HTML email wrapper around body_content."""
    return f"""<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <style>
    body {{ margin: 0; padding: 0; font-family: Arial, sans-serif; background: #f4f4f4; }}
    .container {{ max-width: 600px; margin: 0 auto; background: #ffffff; }}
    .header {{ background: {primary_color}; padding: 24px; text-align: center; }}
    .body {{ padding: 32px; line-height: 1.6; color: #333333; }}
    .button {{ display: inline-block; padding: 12px 24px; background: {primary_color}; color: #ffffff !important; text-decoration: none; border-radius: 4px; font-weight: bold; margin-top: 20px; }}
    .footer {{ padding: 16px; text-align: center; font-size: 12px; color: #888; }}
    @media (max-width: 600px) {{ .container {{ width: 100% !important; }} }}
  </style>
</head>
<body>
  <table width="100%" cellpadding="0" cellspacing="0">
    <tr><td align="center">
      <table class="container" cellpadding="0" cellspacing="0">
        <tr><td class="header"><h1 style="color:#fff;margin:0;">{project_name}</h1></td></tr>
        <tr><td class="body">{body_content}</td></tr>
        <tr><td class="footer">
          <p>{project_name} · <a href="#" style="color:#888;">Unsubscribe</a></p>
        </td></tr>
      </table>
    </td></tr>
  </table>
</body>
</html>"""


async def recover_domain_ir(phase_input: Any, output_dir: Path) -> dict:
    """
    Problem 27 fix: Inline DomainIR recovery when domain_ir_path is missing or broken.
    Re-runs the same extraction logic as p02b using the original spec from p01.
    Returns a minimal ir_data dict (never None).
    """
    data = phase_input.input_data
    requirements: str = data.get("raw_input", "") or data.get("requirements_doc", "")
    app_name: str = data.get("app_name", data.get("project_name", "App"))
    domain: str = data.get("domain", "general")

    logger.warning("p04b: DomainIR missing — attempting inline recovery from spec (domain=%s)", domain)

    # Try importing p02b extraction function first
    try:
        from aether_os.phases.p02b_domain_ir.task_agent import (  # noqa: PLC0415
            _PASS1_PROMPT,
            _PASS4_PROMPT,
            _extract_json,
            _build_ir_from_passes,
        )
        from aether_os.core.llm.client import get_llm_client  # noqa: PLC0415

        llm = get_llm_client()

        async def _call_llm(prompt: str) -> dict:
            try:
                resp = await llm.call(prompt, task_type="analysis", max_tokens=4096)
                return _extract_json(resp)
            except Exception as exc:
                logger.warning("p04b inline recovery LLM error: %s", exc)
                return {}

        p1 = await _call_llm(_PASS1_PROMPT.format(requirements=requirements[:6000], seed_entities="None"))
        if p1.get("entities"):
            p4 = await _call_llm(_PASS4_PROMPT.format(
                requirements=requirements[:4000],
                ir_json=json.dumps(p1, indent=2)[:6000],
            ))
            ir = _build_ir_from_passes(p1, {}, {}, p4 or p1, domain=domain, app_name=app_name)
            recovery_path = output_dir / "domain_ir_recovered.json"
            output_dir.mkdir(parents=True, exist_ok=True)
            ir.save(recovery_path)
            logger.info("p04b: inline IR recovery succeeded — %d entities", len(ir.entities))
            return json.loads(recovery_path.read_text())
    except Exception as exc:
        logger.warning("p04b: inline IR recovery via p02b failed: %s", exc)

    # Last resort: build a minimal stub from app_name
    logger.warning("p04b: using minimal stub IR for app '%s'", app_name)
    stub_entity = "".join(w.capitalize() for w in app_name.split()[:2]) or "Item"
    return {
        "entities": [{"name": stub_entity, "table": stub_entity.lower() + "s", "fields": []}],
        "workflows": [],
        "notifications": [],
        "business_rules": [],
        "permissions": [],
    }
